"""Temperature conversion to degrees Celsius."""


def to_celsius(value: float, unit: str) -> float:
    """Convert ``value`` given in ``unit`` ("C", "F" or "K") to degrees Celsius.

    Unit letters are case-insensitive; any other unit raises ValueError.
    """
    normalized = unit.upper()
    if normalized == "C":
        return value
    if normalized == "F":
        return (value - 32) * 5 / 9
    if normalized == "K":
        return value - 273.15
    raise ValueError(f"unsupported temperature unit: {unit!r}")

import pytest

from units.temperature import to_celsius


def test_celsius_is_unchanged() -> None:
    assert to_celsius(100, "C") == 100


def test_fahrenheit() -> None:
    assert to_celsius(212, "F") == pytest.approx(100.0)


def test_kelvin() -> None:
    assert to_celsius(273.15, "K") == pytest.approx(0.0)


def test_lowercase_units() -> None:
    assert to_celsius(32, "f") == pytest.approx(0.0)


def test_unknown_unit_is_rejected() -> None:
    with pytest.raises(ValueError):
        to_celsius(1, "X")
